template.query:
query GraphAnalytics($analysisType: AnalysisType!, $parameters: AnalysisParameters) {
  graphAnalytics(type: $analysisType, parameters: $parameters) {
    type
    executionTime
    results {
      ... on CentralityAnalysis {
        algorithm
        nodes {
          id
          title
          score
          rank
        }
        statistics {
          min
          max
          average
          median
        }
      }
      ... on ClusteringAnalysis {
        algorithm
        clusters {
          id
          size
          density
          nodes {
            id
            title
          }
          centroids
        }
        modularity
        silhouetteScore
      }
      ... on PathAnalysis {
        algorithm
        paths {
          source
          target
          length
          weight
          nodes {
            id
            title
          }
        }
        statistics {
          shortestPath
          longestPath
          averageLength
        }
      }
    }
    insights {
      keyFindings
      recommendations
      visualizationData
    }
  }
}
